// Lesson: Durable Execution (phase 15 / lesson 12)
// Go port of code/main.py. Go standard library only.
// Source: phases/15-autonomous-systems/12-durable-execution/docs/en.md
// Run: go run code/main.go

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
)

type Event struct {
	Name   string `json:"name"`
	Args   []any  `json:"args"`
	Status string `json:"status"`
	Result any    `json:"result,omitempty"`
}

type EventLog struct {
	Path string
}

func NewEventLog(path string) *EventLog {
	if _, err := os.Stat(path); errors.Is(err, os.ErrNotExist) {
		must(os.WriteFile(path, []byte("[]"), 0o644))
	}
	return &EventLog{Path: path}
}

func (l *EventLog) Events() []Event {
	data, err := os.ReadFile(l.Path)
	must(err)
	var evs []Event
	must(json.Unmarshal(data, &evs))
	return evs
}

func (l *EventLog) Append(ev Event) {
	evs := append(l.Events(), ev)
	data, err := json.Marshal(evs)
	must(err)
	must(os.WriteFile(l.Path, data, 0o644))
}

func sameArgs(a, b []any) bool {
	x, _ := json.Marshal(a)
	y, _ := json.Marshal(b)
	return string(x) == string(y)
}

func (l *EventLog) Lookup(name string, args []any) *Event {
	for _, ev := range l.Events() {
		if ev.Name == name && sameArgs(ev.Args, args) && ev.Status == "done" {
			return &ev
		}
	}
	return nil
}

func must(err error) {
	if err != nil {
		panic(err)
	}
}

func pyRepr(v any) string {
	switch x := v.(type) {
	case nil:
		return "None"
	case bool:
		if x {
			return "True"
		}
		return "False"
	case string:
		return "'" + strings.ReplaceAll(x, "'", "\\'") + "'"
	case float64:
		return strconv.FormatFloat(x, 'f', -1, 64)
	default:
		return fmt.Sprint(x)
	}
}

func pyStr(v any) string {
	if s, ok := v.(string); ok {
		return s
	}
	return pyRepr(v)
}

func tupleRepr(args []any) string {
	parts := make([]string, len(args))
	for i, a := range args {
		parts[i] = pyRepr(a)
	}
	if len(parts) == 1 {
		return "(" + parts[0] + ",)"
	}
	return "(" + strings.Join(parts, ", ") + ")"
}

func normalize(v any) any {
	data, _ := json.Marshal(v)
	var out any
	_ = json.Unmarshal(data, &out)
	return out
}

func activity(name string, fn func(args []any) any) func(*EventLog, ...any) any {
	return func(log *EventLog, args ...any) any {
		if args == nil {
			args = []any{}
		}
		args = normalize(args).([]any)
		if hit := log.Lookup(name, args); hit != nil {
			fmt.Printf("    [replay] %s(%s) -> %s (from log)\n", name, tupleRepr(args), pyStr(hit.Result))
			return hit.Result
		}
		log.Append(Event{Name: name, Args: args, Status: "started"})
		result := normalize(fn(args))
		log.Append(Event{Name: name, Args: args, Status: "done", Result: result})
		fmt.Printf("    [run]    %s(%s) -> %s\n", name, tupleRepr(args), pyStr(result))
		return result
	}
}

var fetchDocs = activity("fetch_docs", func(args []any) any {
	return len(args[0].(string)) * 3
})

var callLLM = activity("call_llm", func(args []any) any {
	return fmt.Sprintf("summary(%s_docs)", pyStr(args[0]))
})

var writeReport = activity("write_report", func(args []any) any {
	return "report://" + args[0].(string)
})

func workflow(log *EventLog, query string, crashAfter int) (string, error) {
	docCount := fetchDocs(log, query)
	if crashAfter == 1 {
		return "", errors.New("simulated crash after fetch_docs")
	}
	summary := callLLM(log, docCount)
	if crashAfter == 2 {
		return "", errors.New("simulated crash after call_llm")
	}
	report := writeReport(log, summary)
	return report.(string), nil
}

func resetLog(path string) *EventLog {
	_ = os.Remove(path)
	return NewEventLog(path)
}

func countRuns(log *EventLog) int {
	n := 0
	for _, ev := range log.Events() {
		if ev.Status == "started" {
			n++
		}
	}
	return n
}

func main() {
	fmt.Println(strings.Repeat("=", 70))
	fmt.Println("DURABLE EXECUTION (Phase 15, Lesson 12)")
	fmt.Println(strings.Repeat("=", 70))

	tmpdir, err := os.MkdirTemp("", "durable")
	must(err)
	defer os.RemoveAll(tmpdir)

	fmt.Println("\nNaive retry (no event log persisted)")
	fmt.Println(strings.Repeat("-", 70))
	for attempt := 1; attempt <= 3; attempt++ {
		log := resetLog(filepath.Join(tmpdir, "naive.json"))
		fmt.Printf("  attempt %d:\n", attempt)
		crash := -1
		if attempt == 1 {
			crash = 2
		}
		r, err := workflow(log, "hello", crash)
		if err != nil {
			fmt.Printf("    -> crash: %s; %d activity starts wasted\n", err, countRuns(log))
			continue
		}
		fmt.Printf("    -> result %s\n", r)
		fmt.Printf("    -> %d activity starts this attempt\n", countRuns(log))
		break
	}

	fmt.Println("\nDurable retry (event log preserved across attempts)")
	fmt.Println(strings.Repeat("-", 70))
	durablePath := filepath.Join(tmpdir, "durable.json")
	_ = os.Remove(durablePath)

	for attempt := 1; attempt <= 3; attempt++ {
		log := NewEventLog(durablePath)
		fmt.Printf("  attempt %d:\n", attempt)
		crash := -1
		if attempt == 1 {
			crash = 2
		}
		r, err := workflow(log, "hello", crash)
		if err != nil {
			fmt.Printf("    -> crash: %s\n", err)
			continue
		}
		fmt.Printf("    -> result %s\n", r)
		fmt.Printf("    -> %d total activity starts across attempts\n", countRuns(log))
		break
	}

	fmt.Println()
	fmt.Println(strings.Repeat("=", 70))
	fmt.Println("HEADLINE: durability makes long-horizon runs affordable to fail")
	fmt.Println(strings.Repeat("-", 70))
	fmt.Println("  Naive retry re-executes every activity on every attempt.")
	fmt.Println("  Durable retry replays completed activities from the log;")
	fmt.Println("  only the missing activity actually runs. Same design used")
	fmt.Println("  by Temporal, LangGraph checkpointing, Microsoft Agent")
	fmt.Println("  Framework, and Claude Code Routines. The LLM call is")
	fmt.Println("  just another non-deterministic activity in the log.")
}

// Lesson: Long-Running Background Agents: Durable Execution (phase 15 / lesson 12)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/15-autonomous-systems/12-durable-execution/docs/en.md
// Run: npx tsx phases/15-autonomous-systems/12-durable-execution/code/main.ts

import * as fs from "node:fs";
import * as os from "node:os";
import * as path from "node:path";

type Arg = string | number;
type Result = string | number;

interface Event {
  name: string;
  args: Arg[];
  status: string;
  result?: Result;
}

class EventLog {
  constructor(public path: string) {
    if (!fs.existsSync(this.path)) {
      fs.writeFileSync(this.path, JSON.stringify([]));
    }
  }

  events(): Event[] {
    return JSON.parse(fs.readFileSync(this.path, "utf8")) as Event[];
  }

  append(ev: Event): void {
    const evs = this.events();
    evs.push(ev);
    fs.writeFileSync(this.path, JSON.stringify(evs));
  }

  lookup(name: string, args: Arg[]): Event | null {
    for (const ev of this.events()) {
      if (
        ev.name === name &&
        JSON.stringify(ev.args) === JSON.stringify(args) &&
        ev.status === "done"
      ) {
        return ev;
      }
    }
    return null;
  }
}

function pyRepr(v: Arg): string {
  return typeof v === "string" ? `'${v}'` : String(v);
}

function pyTuple(args: Arg[]): string {
  if (args.length === 1) {
    return `(${pyRepr(args[0])},)`;
  }
  return `(${args.map(pyRepr).join(", ")})`;
}

function activity<A extends Arg, R extends Result>(
  name: string,
  fn: (arg: A) => R,
): (log: EventLog, arg: A) => R {
  return (log: EventLog, arg: A): R => {
    const args: Arg[] = [arg];
    const hit = log.lookup(name, args);
    if (hit) {
      console.log(`    [replay] ${name}(${pyTuple(args)}) -> ${hit.result} (from log)`);
      return hit.result as R;
    }
    log.append({ name, args, status: "started" });
    const result = fn(arg);
    log.append({ name, args, status: "done", result });
    console.log(`    [run]    ${name}(${pyTuple(args)}) -> ${result}`);
    return result;
  };
}

const fetchDocs = activity("fetch_docs", (query: string): number => query.length * 3);

const callLlm = activity("call_llm", (docCount: number): string => `summary(${docCount}_docs)`);

const writeReport = activity("write_report", (summary: string): string => `report://${summary}`);

class RuntimeError extends Error {}

function workflow(log: EventLog, query: string, crashAfter: number = -1): string {
  const docCount = fetchDocs(log, query);
  if (crashAfter === 1) {
    throw new RuntimeError("simulated crash after fetch_docs");
  }
  const summary = callLlm(log, docCount);
  if (crashAfter === 2) {
    throw new RuntimeError("simulated crash after call_llm");
  }
  const report = writeReport(log, summary);
  return report;
}

function resetLog(p: string): EventLog {
  if (fs.existsSync(p)) {
    fs.rmSync(p);
  }
  return new EventLog(p);
}

function countRuns(log: EventLog): number {
  return log.events().filter((ev) => ev.status === "started").length;
}

function main(): void {
  console.log("=".repeat(70));
  console.log("DURABLE EXECUTION (Phase 15, Lesson 12)");
  console.log("=".repeat(70));

  const tmpdir = fs.mkdtempSync(path.join(os.tmpdir(), "durable-"));

  console.log("\nNaive retry (no event log persisted)");
  console.log("-".repeat(70));
  for (let attempt = 1; attempt < 4; attempt++) {
    const log = resetLog(path.join(tmpdir, "naive.json"));
    console.log(`  attempt ${attempt}:`);
    try {
      const crash = attempt === 1 ? 2 : -1;
      const r = workflow(log, "hello", crash);
      console.log(`    -> result ${r}`);
      console.log(`    -> ${countRuns(log)} activity starts this attempt`);
      break;
    } catch (e) {
      if (!(e instanceof RuntimeError)) {
        throw e;
      }
      console.log(`    -> crash: ${e.message}; ${countRuns(log)} activity starts wasted`);
    }
  }

  console.log("\nDurable retry (event log preserved across attempts)");
  console.log("-".repeat(70));
  const durablePath = path.join(tmpdir, "durable.json");
  if (fs.existsSync(durablePath)) {
    fs.rmSync(durablePath);
  }

  for (let attempt = 1; attempt < 4; attempt++) {
    const log = new EventLog(durablePath);
    console.log(`  attempt ${attempt}:`);
    try {
      const crash = attempt === 1 ? 2 : -1;
      const r = workflow(log, "hello", crash);
      console.log(`    -> result ${r}`);
      console.log(`    -> ${countRuns(log)} total activity starts across attempts`);
      break;
    } catch (e) {
      if (!(e instanceof RuntimeError)) {
        throw e;
      }
      console.log(`    -> crash: ${e.message}`);
    }
  }

  console.log();
  console.log("=".repeat(70));
  console.log("HEADLINE: durability makes long-horizon runs affordable to fail");
  console.log("-".repeat(70));
  console.log("  Naive retry re-executes every activity on every attempt.");
  console.log("  Durable retry replays completed activities from the log;");
  console.log("  only the missing activity actually runs. Same design used");
  console.log("  by Temporal, LangGraph checkpointing, Microsoft Agent");
  console.log("  Framework, and Claude Code Routines. The LLM call is");
  console.log("  just another non-deterministic activity in the log.");
}

main();
